CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','user') NOT NULL DEFAULT 'user',plan ENUM('free','basic','premium') NOT NULL DEFAULT 'free',status ENUM('active','disabled') NOT NULL DEFAULT 'active',timezone VARCHAR(80) NOT NULL DEFAULT 'Asia/Kolkata',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,must_reset_password TINYINT(1) NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS projects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,description TEXT,status ENUM('Planning','Active','Completed','Archived') NOT NULL DEFAULT 'Active',start_date DATE NULL,due_date DATE NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),CONSTRAINT fk_project_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tasks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NOT NULL,assigned_user_id BIGINT UNSIGNED NULL,title VARCHAR(220) NOT NULL,description TEXT,status ENUM('Todo','In Progress','Completed') NOT NULL DEFAULT 'Todo',priority ENUM('Low','Medium','High') NOT NULL DEFAULT 'Medium',due_date DATE NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),INDEX(project_id),INDEX(status),INDEX(priority),INDEX(created_at),CONSTRAINT fk_task_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_task_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL,CONSTRAINT fk_task_assignee FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS note_categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,UNIQUE KEY uq_note_category(user_id,name),CONSTRAINT fk_category_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NULL,title VARCHAR(220) NOT NULL,content LONGTEXT NOT NULL,is_pinned TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),INDEX(is_pinned),CONSTRAINT fk_note_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_note_category FOREIGN KEY(category_id) REFERENCES note_categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS milestones(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,due_date DATE NULL,status ENUM('Pending','Completed') NOT NULL DEFAULT 'Pending',created_at DATETIME NOT NULL,CONSTRAINT fk_milestone_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS conversations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED NULL,title VARCHAR(180) NOT NULL,model_id VARCHAR(190) NULL,is_pinned TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id,updated_at),INDEX(project_id),CONSTRAINT fk_conversation_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_conversation_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS conversation_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT UNSIGNED NOT NULL,role ENUM('user','assistant','system') NOT NULL,content LONGTEXT NOT NULL,created_at DATETIME NOT NULL,CONSTRAINT fk_message_conversation FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ai_user_preferences(user_id BIGINT UNSIGNED PRIMARY KEY,model_id VARCHAR(190) NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_ai_preferences_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ai_project_settings(project_id BIGINT UNSIGNED PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,custom_instructions TEXT NULL,context_text LONGTEXT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),CONSTRAINT fk_ai_project_settings_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,CONSTRAINT fk_ai_project_settings_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS system_settings(setting_key VARCHAR(120) PRIMARY KEY,setting_value TEXT NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS email_settings(id TINYINT UNSIGNED PRIMARY KEY,provider VARCHAR(40) NOT NULL DEFAULT 'smtp',host VARCHAR(190),port INT,username VARCHAR(190),password_encrypted TEXT,from_email VARCHAR(190),from_name VARCHAR(120),updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ai_settings(id TINYINT UNSIGNED PRIMARY KEY,provider VARCHAR(40) NOT NULL DEFAULT 'bedrock',access_key_encrypted TEXT,secret_key_encrypted TEXT,region VARCHAR(80),model_id VARCHAR(190),updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS activity_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,event_type VARCHAR(80) NOT NULL,ip_address VARCHAR(45),created_at DATETIME NOT NULL,INDEX(user_id),INDEX(event_type),INDEX(created_at),CONSTRAINT fk_activity_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS contact_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,subject VARCHAR(220) NOT NULL,message TEXT NOT NULL,ip_address VARCHAR(45),created_at DATETIME NOT NULL,INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS password_resets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME NOT NULL,INDEX(token_hash),CONSTRAINT fk_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS schema_version(version INT UNSIGNED PRIMARY KEY,executed_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ai_usage_daily(user_id BIGINT UNSIGNED NOT NULL,usage_date DATE NOT NULL,input_units INT UNSIGNED NOT NULL DEFAULT 0,output_units INT UNSIGNED NOT NULL DEFAULT 0,active_seconds DECIMAL(12,3) UNSIGNED NOT NULL DEFAULT 0,updated_at DATETIME NOT NULL,PRIMARY KEY(user_id,usage_date),CONSTRAINT fk_ai_usage_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_ai_settings(user_id BIGINT UNSIGNED PRIMARY KEY,bedrock_api_key_encrypted TEXT NULL,aws_access_key_encrypted TEXT NULL,aws_secret_key_encrypted TEXT NULL,aws_session_token_encrypted TEXT NULL,region VARCHAR(80) NULL,model_id VARCHAR(190) NULL,endpoint_url TEXT NULL,api_mode VARCHAR(30) NULL,transport VARCHAR(30) NULL,relay_url TEXT NULL,relay_token_encrypted TEXT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_user_ai_settings_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS site_content(page_slug VARCHAR(80) PRIMARY KEY,title VARCHAR(180) NOT NULL DEFAULT '',html_content LONGTEXT NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS media_assets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,name VARCHAR(180) NOT NULL,alt_text VARCHAR(500) NULL,description TEXT NULL,folder_name VARCHAR(180) NOT NULL DEFAULT 'General',source_type ENUM('upload','url') NOT NULL,source_category VARCHAR(80) NOT NULL DEFAULT 'Media Assets',source_ref_id BIGINT UNSIGNED NULL,canonical_file_id BIGINT UNSIGNED NULL,source_url TEXT NOT NULL,storage_path VARCHAR(255) NULL,mime_type VARCHAR(150) NULL,size_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,kind ENUM('image','audio','video','archive','file') NOT NULL DEFAULT 'image',width INT UNSIGNED NULL,height INT UNSIGNED NULL,auto_fit TINYINT(1) NOT NULL DEFAULT 1,is_favorite TINYINT(1) NOT NULL DEFAULT 0,deleted_at DATETIME NULL,deleted_by BIGINT UNSIGNED NULL,content_sha256 CHAR(64) NULL,last_accessed_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NULL,INDEX(created_at),INDEX idx_media_trash_user_deleted(user_id,deleted_at),INDEX idx_media_hash_user(user_id,content_sha256),INDEX idx_media_recent(user_id,last_accessed_at),INDEX(folder_name),INDEX(kind),INDEX(is_favorite,created_at),INDEX(name),INDEX idx_media_user_folder(user_id,folder_name),INDEX idx_media_user_created(user_id,created_at),INDEX idx_media_source_category(user_id,source_category,created_at),INDEX idx_media_canonical_file(user_id,canonical_file_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS shared_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,token CHAR(64) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,type ENUM('message','conversation') NOT NULL,conversation_id BIGINT UNSIGNED NULL,message_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,INDEX(conversation_id),INDEX(message_id),CONSTRAINT fk_share_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_share_conv FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,CONSTRAINT fk_share_msg FOREIGN KEY(message_id) REFERENCES conversation_messages(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS subscription_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,plan ENUM('basic','premium') NOT NULL,amount DECIMAL(10,2) NOT NULL,payment_method ENUM('UPI','PhonePe','Google Pay','Net Banking','Bank Transfer') NOT NULL,waiting_token CHAR(20) NOT NULL UNIQUE,status ENUM('waiting','proof_uploaded','approved','rejected') NOT NULL DEFAULT 'waiting',proof_path VARCHAR(255) NULL,admin_note TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),INDEX(status),CONSTRAINT fk_sub_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS support_threads(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,subscription_request_id BIGINT UNSIGNED NULL,status ENUM('open','closed') NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),CONSTRAINT fk_thread_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_thread_sub FOREIGN KEY(subscription_request_id) REFERENCES subscription_requests(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS support_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,thread_id BIGINT UNSIGNED NOT NULL,sender_user_id BIGINT UNSIGNED NULL,sender_role ENUM('user','admin') NOT NULL,body LONGTEXT NOT NULL,attachment_path VARCHAR(255) NULL,attachment_paths LONGTEXT NULL,attachment_category VARCHAR(80) NULL,created_at DATETIME NOT NULL,INDEX(thread_id),CONSTRAINT fk_support_thread FOREIGN KEY(thread_id) REFERENCES support_threads(id) ON DELETE CASCADE,CONSTRAINT fk_support_sender FOREIGN KEY(sender_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS chat_attachments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT UNSIGNED NOT NULL,message_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(220) NOT NULL,stored_path VARCHAR(255) NOT NULL,storage_path VARCHAR(900) NULL,mime_type VARCHAR(150) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,kind ENUM('image','audio','video','archive','file') NOT NULL DEFAULT 'file',source_type VARCHAR(40) NOT NULL DEFAULT 'ai',source_category VARCHAR(80) NOT NULL DEFAULT 'AI Workspace',created_at DATETIME NOT NULL,INDEX(conversation_id),INDEX(user_id),INDEX idx_chat_source_category(user_id,source_category,created_at),CONSTRAINT fk_chat_attach_conv FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,CONSTRAINT fk_chat_attach_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_chat_attach_msg FOREIGN KEY(message_id) REFERENCES conversation_messages(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS short_links(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,slug VARCHAR(64) NOT NULL UNIQUE,destination_url TEXT NOT NULL,title VARCHAR(220) NULL,password_hash VARCHAR(255) NULL,expires_at DATETIME NULL,max_clicks BIGINT UNSIGNED NOT NULL DEFAULT 0,clicks BIGINT UNSIGNED NOT NULL DEFAULT 0,last_clicked_at DATETIME NULL,allowed_countries TEXT NULL,blocked_countries TEXT NULL,routing_rules LONGTEXT NULL,deep_link_url TEXT NULL,web_fallback_url TEXT NULL,utm_json TEXT NULL,tracking_pixels LONGTEXT NULL,og_title VARCHAR(220) NULL,og_description TEXT NULL,og_image_url TEXT NULL,status ENUM('active','disabled','expired') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),INDEX(status),INDEX(expires_at),INDEX(clicks),CONSTRAINT fk_short_link_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS qr_designs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,link_id BIGINT UNSIGNED NOT NULL UNIQUE,design_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(link_id),CONSTRAINT fk_qr_design_link FOREIGN KEY(link_id) REFERENCES short_links(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS link_clicks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,link_id BIGINT UNSIGNED NOT NULL,visitor_hash CHAR(64) NOT NULL,ip_hash CHAR(64) NOT NULL,ip_address VARCHAR(45) NULL,referrer VARCHAR(500) NULL,browser VARCHAR(80) NOT NULL,browser_version VARCHAR(40) NULL,browser_engine VARCHAR(40) NULL,os VARCHAR(50) NOT NULL,os_version VARCHAR(40) NULL,device_category VARCHAR(30) NOT NULL,device_brand VARCHAR(80) NULL,device_model VARCHAR(120) NULL,country_code CHAR(2) NULL,country_name VARCHAR(120) NULL,region VARCHAR(120) NULL,city VARCHAR(120) NULL,postal_code VARCHAR(30) NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,timezone_name VARCHAR(80) NULL,isp VARCHAR(190) NULL,asn VARCHAR(40) NULL,accept_language VARCHAR(120) NULL,utm_source VARCHAR(190) NULL,utm_medium VARCHAR(190) NULL,utm_campaign VARCHAR(190) NULL,utm_term VARCHAR(190) NULL,utm_content VARCHAR(190) NULL,is_bot TINYINT(1) NOT NULL DEFAULT 0,bot_type VARCHAR(80) NULL,user_agent VARCHAR(1000) NULL,clicked_at DATETIME NOT NULL,clicked_at_utc DATETIME NULL,INDEX(link_id),INDEX(clicked_at),INDEX(link_id,clicked_at),INDEX(link_id,is_bot),INDEX(link_id,visitor_hash),CONSTRAINT fk_link_click_link FOREIGN KEY(link_id) REFERENCES short_links(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS link_api_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,label VARCHAR(120) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,token_prefix VARCHAR(20) NOT NULL,created_at DATETIME NOT NULL,last_used_at DATETIME NULL,revoked_at DATETIME NULL,INDEX(user_id),CONSTRAINT fk_link_token_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS link_webhooks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,link_id BIGINT UNSIGNED NULL,url TEXT NOT NULL,secret VARCHAR(190) NOT NULL,events_json TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,INDEX(user_id),INDEX(link_id),CONSTRAINT fk_link_webhook_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_link_webhook_link FOREIGN KEY(link_id) REFERENCES short_links(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS link_webhook_deliveries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,webhook_id BIGINT UNSIGNED NOT NULL,event_name VARCHAR(80) NOT NULL,status_code INT NOT NULL DEFAULT 0,response_body TEXT NULL,created_at DATETIME NOT NULL,INDEX(webhook_id),INDEX(created_at),CONSTRAINT fk_webhook_delivery_hook FOREIGN KEY(webhook_id) REFERENCES link_webhooks(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS link_rate_limits(bucket CHAR(64) PRIMARY KEY,window_start DATETIME NOT NULL,hits INT UNSIGNED NOT NULL DEFAULT 0,INDEX(window_start)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_objects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,public_token CHAR(32) NOT NULL UNIQUE,object_key VARCHAR(600) NOT NULL UNIQUE,original_name VARCHAR(220) NOT NULL,relative_path VARCHAR(600) NULL,mime_type VARCHAR(150) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,kind VARCHAR(30) NOT NULL DEFAULT 'file',source_type VARCHAR(40) NOT NULL DEFAULT 'storage',source_category VARCHAR(80) NOT NULL DEFAULT 'Shared Files',etag VARCHAR(120) NULL,storage_driver VARCHAR(30) NOT NULL DEFAULT 'local',provider_url TEXT NULL,status ENUM('pending','clean','quarantined','expired','deleted') NOT NULL DEFAULT 'pending',trashed_at DATETIME NULL,trashed_by BIGINT UNSIGNED NULL,scan_status ENUM('pending','clean','infected','failed','skipped') NOT NULL DEFAULT 'pending',password_hash VARCHAR(255) NULL,expires_at DATETIME NULL,max_downloads BIGINT UNSIGNED NOT NULL DEFAULT 0,downloads BIGINT UNSIGNED NOT NULL DEFAULT 0,burn_after_reading TINYINT(1) NOT NULL DEFAULT 0,view_only TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),INDEX(status),INDEX idx_file_trash_user_time(user_id,trashed_at),INDEX(expires_at),INDEX(scan_status),INDEX(downloads),INDEX idx_file_source_category(user_id,source_category,created_at),CONSTRAINT fk_file_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS upload_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token CHAR(64) NOT NULL UNIQUE,scope VARCHAR(30) NOT NULL,context_id BIGINT UNSIGNED NOT NULL DEFAULT 0,original_name VARCHAR(220) NOT NULL,relative_path VARCHAR(600) NULL,source_type VARCHAR(40) NOT NULL DEFAULT 'files',source_category VARCHAR(80) NOT NULL DEFAULT 'Shared Files',target_folder VARCHAR(600) NULL,mime_type VARCHAR(150) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,received_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,temp_path VARCHAR(900) NOT NULL,final_path VARCHAR(900) NULL,public_path VARCHAR(900) NULL,status ENUM('uploading','completed','aborted','failed') NOT NULL DEFAULT 'uploading',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id,status),INDEX(user_id,created_at),CONSTRAINT fk_upload_session_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_uploads(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,file_id BIGINT UNSIGNED NOT NULL,upload_id VARCHAR(255) NOT NULL,parts_json LONGTEXT NULL,expected_parts INT UNSIGNED NOT NULL DEFAULT 0,completed_parts INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('initiated','uploading','completed','aborted','failed') NOT NULL DEFAULT 'initiated',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_file_upload(file_id),CONSTRAINT fk_file_upload_file FOREIGN KEY(file_id) REFERENCES file_objects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,file_id BIGINT UNSIGNED NOT NULL,event_type ENUM('view','download','download_complete','download_aborted') NOT NULL,visitor_hash CHAR(64) NOT NULL,ip_hash CHAR(64) NOT NULL,referrer VARCHAR(500) NULL,browser VARCHAR(80) NOT NULL,os VARCHAR(50) NOT NULL,device_category VARCHAR(30) NOT NULL,country_code CHAR(2) NULL,city VARCHAR(120) NULL,is_bot TINYINT(1) NOT NULL DEFAULT 0,bytes_transferred BIGINT UNSIGNED NOT NULL DEFAULT 0,completed TINYINT(1) NOT NULL DEFAULT 0,occurred_at DATETIME NOT NULL,INDEX(file_id),INDEX(file_id,occurred_at),INDEX(file_id,event_type),INDEX(file_id,is_bot),CONSTRAINT fk_file_event_file FOREIGN KEY(file_id) REFERENCES file_objects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_webhooks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,url TEXT NOT NULL,secret VARCHAR(190) NOT NULL,events_json TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,INDEX(user_id),CONSTRAINT fk_file_webhook_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_webhook_deliveries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,webhook_id BIGINT UNSIGNED NOT NULL,event_name VARCHAR(80) NOT NULL,status_code INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,INDEX(webhook_id),INDEX(created_at),CONSTRAINT fk_file_delivery_hook FOREIGN KEY(webhook_id) REFERENCES file_webhooks(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_api_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,label VARCHAR(120) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,token_prefix VARCHAR(20) NOT NULL,created_at DATETIME NOT NULL,last_used_at DATETIME NULL,revoked_at DATETIME NULL,INDEX(user_id),CONSTRAINT fk_file_token_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_abuse_blocks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_hash CHAR(64) NOT NULL UNIQUE,ip_encrypted TEXT NULL,reason VARCHAR(255) NOT NULL,expires_at DATETIME NULL,created_at DATETIME NOT NULL,INDEX(expires_at));
CREATE TABLE IF NOT EXISTS file_abuse_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_hash CHAR(64) NOT NULL,ip_encrypted TEXT NULL,action ENUM('block','unblock') NOT NULL,duration_label VARCHAR(40) NULL,reason VARCHAR(255) NULL,admin_user_id BIGINT UNSIGNED NULL,expires_at DATETIME NULL,created_at DATETIME NOT NULL,INDEX(ip_hash),INDEX(created_at),CONSTRAINT fk_abuse_history_admin FOREIGN KEY(admin_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS policy_user_overrides(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,policy_key VARCHAR(120) NOT NULL,policy_value LONGTEXT NOT NULL,reason VARCHAR(255) NULL,granted_by BIGINT UNSIGNED NULL,expires_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_user_policy(user_id,policy_key),INDEX(user_id),CONSTRAINT fk_policy_override_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_policy_override_admin FOREIGN KEY(granted_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS policy_audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,before_json LONGTEXT NULL,after_json LONGTEXT NULL,ip_address VARCHAR(45) NULL,created_at DATETIME NOT NULL,INDEX(admin_id),INDEX(action),INDEX(created_at),CONSTRAINT fk_policy_audit_admin FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,permissions_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_admin_roles(user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(user_id,role_id),CONSTRAINT fk_user_admin_role_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_user_admin_role_role FOREIGN KEY(role_id) REFERENCES admin_roles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_impersonation_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NOT NULL,target_user_id BIGINT UNSIGNED NOT NULL,action VARCHAR(30) NOT NULL,ip_address VARCHAR(45) NULL,created_at DATETIME NOT NULL,INDEX(admin_id),INDEX(target_user_id),INDEX(created_at),CONSTRAINT fk_imp_admin FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_imp_target FOREIGN KEY(target_user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS global_block_rules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rule_type ENUM('ip','cidr','country','user') NOT NULL,value VARCHAR(190) NOT NULL,action ENUM('block','throttle') NOT NULL DEFAULT 'block',limit_mbps DECIMAL(10,2) NULL,reason VARCHAR(255) NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_global_block(rule_type,value),INDEX(active),CONSTRAINT fk_global_block_admin FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS webhook_delivery_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,scope VARCHAR(30) NOT NULL,event_name VARCHAR(100) NOT NULL,target_url TEXT NOT NULL,status_code INT NOT NULL DEFAULT 0,response_excerpt TEXT NULL,created_at DATETIME NOT NULL,INDEX(scope),INDEX(event_name),INDEX(status_code),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- V10.2 Code Editor Module
CREATE TABLE IF NOT EXISTS code_snippets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,title VARCHAR(220) NOT NULL,language VARCHAR(40) NOT NULL DEFAULT 'text',category VARCHAR(100) NULL,tags_json TEXT NULL,code_text LONGTEXT NOT NULL,privacy ENUM('public','unlisted','private') NOT NULL DEFAULT 'unlisted',password_hash VARCHAR(255) NULL,expires_at DATETIME NULL,burn_after_read TINYINT(1) NOT NULL DEFAULT 0,views BIGINT UNSIGNED NOT NULL DEFAULT 0,token CHAR(32) NOT NULL UNIQUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,published_at DATETIME NULL,author_country VARCHAR(8) NULL,author_city VARCHAR(120) NULL,status ENUM('active','expired','deleted') NOT NULL DEFAULT 'active',INDEX(user_id),INDEX(parent_id),INDEX(category),INDEX(language),INDEX(privacy),INDEX(expires_at),INDEX(views),CONSTRAINT fk_code_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_code_parent FOREIGN KEY(parent_id) REFERENCES code_snippets(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS code_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,snippet_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,code_text LONGTEXT NOT NULL,language VARCHAR(40) NOT NULL,title VARCHAR(220) NOT NULL,category VARCHAR(100) NULL,tags_json TEXT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_code_version(snippet_id,version_no),INDEX(snippet_id),INDEX(user_id),CONSTRAINT fk_code_version_snippet FOREIGN KEY(snippet_id) REFERENCES code_snippets(id) ON DELETE CASCADE,CONSTRAINT fk_code_version_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS code_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_code_category(user_id,name),INDEX(user_id),CONSTRAINT fk_code_category_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS code_access_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,snippet_id BIGINT UNSIGNED NOT NULL,event_type ENUM('view','share','execute') NOT NULL,visitor_hash CHAR(64) NULL,user_agent VARCHAR(500) NULL,country_code VARCHAR(8) NULL,city VARCHAR(120) NULL,referrer VARCHAR(500) NULL,created_at DATETIME NOT NULL,INDEX(snippet_id),INDEX(event_type),INDEX(created_at),CONSTRAINT fk_code_event_snippet FOREIGN KEY(snippet_id) REFERENCES code_snippets(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS documentation_entries (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 slug VARCHAR(180) NOT NULL UNIQUE,
 title VARCHAR(220) NOT NULL,
 summary VARCHAR(500) NOT NULL,
 section VARCHAR(120) NOT NULL DEFAULT 'General',
 overview LONGTEXT NOT NULL,
 requirements LONGTEXT NOT NULL,
 steps_json LONGTEXT NOT NULL,
 examples_html LONGTEXT NOT NULL,
 troubleshooting_json LONGTEXT NOT NULL,
 official_json LONGTEXT NOT NULL,
 visibility ENUM('private','shared') NOT NULL DEFAULT 'private',
 updated_by BIGINT UNSIGNED NULL,
 updated_at DATETIME NOT NULL,
 INDEX(section), INDEX(updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS storage_connections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(40) NOT NULL UNIQUE,account_email VARCHAR(190) NULL,access_token_encrypted TEXT NULL,refresh_token_encrypted TEXT NULL,expires_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- CMS Overhaul: WordPress-style content, taxonomy, revisions and comments
CREATE TABLE IF NOT EXISTS cms_categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,parent_id BIGINT UNSIGNED NULL,description TEXT NULL,archive_color VARCHAR(7) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(parent_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cms_posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,post_type ENUM('post','page') NOT NULL DEFAULT 'post',title VARCHAR(220) NOT NULL DEFAULT '',slug VARCHAR(220) NOT NULL,content LONGTEXT NOT NULL,excerpt TEXT NULL,status ENUM('draft','published','trash','private','pending') NOT NULL DEFAULT 'draft',visibility ENUM('public','private','password') NOT NULL DEFAULT 'public',password_hash VARCHAR(255) NULL,author_id BIGINT UNSIGNED NULL,parent_id BIGINT UNSIGNED NULL,template VARCHAR(120) NULL,menu_order INT NOT NULL DEFAULT 0,featured_image_url TEXT NULL,transparent_header TINYINT(1) NOT NULL DEFAULT 0,display_title TINYINT(1) NOT NULL DEFAULT 1,layout VARCHAR(40) NOT NULL DEFAULT 'default',content_style VARCHAR(40) NOT NULL DEFAULT 'default',vertical_padding VARCHAR(40) NOT NULL DEFAULT 'default',comments_enabled TINYINT(1) NOT NULL DEFAULT 1,pings_enabled TINYINT(1) NOT NULL DEFAULT 1,scheduled_at DATETIME NULL,published_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,UNIQUE KEY uq_cms_post_slug_type(post_type,slug),INDEX(post_type),INDEX(status),INDEX(author_id),INDEX(parent_id),INDEX(updated_at),CONSTRAINT fk_cms_post_author FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_cms_post_parent FOREIGN KEY(parent_id) REFERENCES cms_posts(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cms_tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cms_post_tags (post_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(post_id,tag_id),CONSTRAINT fk_cms_pt_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE,CONSTRAINT fk_cms_pt_tag FOREIGN KEY(tag_id) REFERENCES cms_tags(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cms_post_categories (post_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(post_id,category_id),CONSTRAINT fk_cms_pc_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE,CONSTRAINT fk_cms_pc_cat FOREIGN KEY(category_id) REFERENCES cms_categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cms_revisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,post_id BIGINT UNSIGNED NOT NULL,revision_no INT UNSIGNED NOT NULL,title VARCHAR(220) NOT NULL,slug VARCHAR(220) NOT NULL,content LONGTEXT NOT NULL,meta_json LONGTEXT NOT NULL,author_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_cms_revision(post_id,revision_no),INDEX(post_id),CONSTRAINT fk_cms_revision_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE,CONSTRAINT fk_cms_revision_author FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cms_comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,post_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,author_name VARCHAR(180) NOT NULL,author_email VARCHAR(190) NULL,author_url VARCHAR(500) NULL,content TEXT NOT NULL,status ENUM('pending','approved','spam','trash') NOT NULL DEFAULT 'pending',ip_hash CHAR(64) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(post_id),INDEX(status),INDEX(created_at),CONSTRAINT fk_cms_comment_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE,CONSTRAINT fk_cms_comment_parent FOREIGN KEY(parent_id) REFERENCES cms_comments(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cms_post_meta (post_id BIGINT UNSIGNED NOT NULL,meta_key VARCHAR(120) NOT NULL,meta_value LONGTEXT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(post_id,meta_key),CONSTRAINT fk_cms_meta_post FOREIGN KEY(post_id) REFERENCES cms_posts(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS cms_user_preferences(user_id BIGINT UNSIGNED NOT NULL,pref_key VARCHAR(120) NOT NULL,pref_value LONGTEXT NULL,updated_at DATETIME NOT NULL,PRIMARY KEY(user_id,pref_key),INDEX(pref_key),CONSTRAINT fk_cms_pref_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- V11.31 live click stream queue (GeoIP provider pool replaced by local database in V11.42)
CREATE TABLE IF NOT EXISTS link_click_queue(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,link_id BIGINT UNSIGNED NOT NULL,payload_json LONGTEXT NOT NULL,status ENUM('pending','processing','done','failed') NOT NULL DEFAULT 'pending',attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,available_at DATETIME NOT NULL,locked_at DATETIME NULL,processed_at DATETIME NULL,last_error VARCHAR(500) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(status,available_at),INDEX(link_id,created_at),CONSTRAINT fk_click_queue_link FOREIGN KEY(link_id) REFERENCES short_links(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- V11.36 user media tenancy indexes (bootstrap applies these idempotently).

-- V11.37 upload/sharing hardening
CREATE TABLE IF NOT EXISTS file_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,file_id BIGINT UNSIGNED NOT NULL,version_no INT UNSIGNED NOT NULL,object_key VARCHAR(600) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,etag VARCHAR(120) NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_file_version(file_id,version_no),INDEX(file_id,created_at),CONSTRAINT fk_file_version_file FOREIGN KEY(file_id) REFERENCES file_objects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_share_links(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,link_id BIGINT UNSIGNED NULL,token CHAR(48) NOT NULL UNIQUE,title VARCHAR(220) NOT NULL,password_hash VARCHAR(255) NULL,expires_at DATETIME NULL,revoked_at DATETIME NULL,max_downloads BIGINT UNSIGNED NOT NULL DEFAULT 0,downloads BIGINT UNSIGNED NOT NULL DEFAULT 0,view_only TINYINT(1) NOT NULL DEFAULT 0,theme_json TEXT NULL,og_title VARCHAR(220) NULL,og_description TEXT NULL,og_image_url TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(user_id),INDEX(expires_at),INDEX(link_id),CONSTRAINT fk_file_share_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS file_share_items(share_id BIGINT UNSIGNED NOT NULL,file_id BIGINT UNSIGNED NOT NULL,sort_order INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(share_id,file_id),CONSTRAINT fk_file_share_item_share FOREIGN KEY(share_id) REFERENCES file_share_links(id) ON DELETE CASCADE,CONSTRAINT fk_file_share_item_file FOREIGN KEY(file_id) REFERENCES file_objects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- V11.40 Advanced Analytics
-- PocketCat V11.40 - Advanced Website Analytics, Tracking & Review Intelligence
-- Runtime bootstrap also creates these tables idempotently through includes/analytics.php.
CREATE TABLE IF NOT EXISTS analytics_sites(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,domain VARCHAR(255) NULL,tracking_key VARCHAR(80) NOT NULL UNIQUE,enabled TINYINT(1) NOT NULL DEFAULT 1,consent_required TINYINT(1) NOT NULL DEFAULT 1,anonymize_ip TINYINT(1) NOT NULL DEFAULT 1,retention_days INT UNSIGNED NOT NULL DEFAULT 365,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(owner_user_id),INDEX(enabled),CONSTRAINT fk_analytics_site_owner FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS analytics_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NOT NULL,session_hash CHAR(64) NOT NULL,visitor_hash CHAR(64) NOT NULL,started_at DATETIME NOT NULL,last_seen_at DATETIME NOT NULL,landing_path VARCHAR(500) NULL,exit_path VARCHAR(500) NULL,pageviews INT UNSIGNED NOT NULL DEFAULT 0,event_count INT UNSIGNED NOT NULL DEFAULT 0,engagement_seconds INT UNSIGNED NOT NULL DEFAULT 0,converted TINYINT(1) NOT NULL DEFAULT 0,referrer VARCHAR(500) NULL,utm_source VARCHAR(190) NULL,utm_medium VARCHAR(190) NULL,utm_campaign VARCHAR(190) NULL,country_code CHAR(2) NULL,country_name VARCHAR(120) NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,timezone_name VARCHAR(80) NULL,device_category VARCHAR(30) NULL,browser VARCHAR(80) NULL,os VARCHAR(50) NULL,ip_hash CHAR(64) NULL,INDEX(site_id,last_seen_at),INDEX(site_id,started_at),INDEX(site_id,visitor_hash),INDEX(site_id,session_hash),CONSTRAINT fk_analytics_session_site FOREIGN KEY(site_id) REFERENCES analytics_sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS analytics_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NOT NULL,session_hash CHAR(64) NOT NULL,visitor_hash CHAR(64) NOT NULL,event_name VARCHAR(80) NOT NULL,page_path VARCHAR(500) NULL,page_title VARCHAR(220) NULL,referrer VARCHAR(500) NULL,utm_source VARCHAR(190) NULL,utm_medium VARCHAR(190) NULL,utm_campaign VARCHAR(190) NULL,utm_term VARCHAR(190) NULL,utm_content VARCHAR(190) NULL,country_code CHAR(2) NULL,country_name VARCHAR(120) NULL,region VARCHAR(120) NULL,city VARCHAR(120) NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,timezone_name VARCHAR(80) NULL,device_category VARCHAR(30) NULL,browser VARCHAR(80) NULL,browser_version VARCHAR(40) NULL,os VARCHAR(50) NULL,screen_width SMALLINT UNSIGNED NULL,screen_height SMALLINT UNSIGNED NULL,language VARCHAR(40) NULL,ip_hash CHAR(64) NULL,event_value DECIMAL(18,4) NULL,metadata_json TEXT NULL,created_at DATETIME NOT NULL,INDEX(site_id,created_at),INDEX(site_id,event_name,created_at),INDEX(site_id,page_path(191),created_at),INDEX(site_id,session_hash),INDEX(site_id,visitor_hash),CONSTRAINT fk_analytics_event_site FOREIGN KEY(site_id) REFERENCES analytics_sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS analytics_goals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,event_name VARCHAR(80) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX(site_id,active),CONSTRAINT fk_analytics_goal_site FOREIGN KEY(site_id) REFERENCES analytics_sites(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS file_share_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,share_id BIGINT UNSIGNED NOT NULL,file_id BIGINT UNSIGNED NULL,event_type VARCHAR(40) NOT NULL,visitor_hash CHAR(64) NULL,ip_hash CHAR(64) NULL,referrer VARCHAR(500) NULL,user_agent VARCHAR(1000) NULL,occurred_at DATETIME NOT NULL,INDEX idx_share_event(share_id,occurred_at),INDEX idx_share_event_type(share_id,event_type,occurred_at),CONSTRAINT fk_file_share_event_share FOREIGN KEY(share_id) REFERENCES file_share_links(id) ON DELETE CASCADE,CONSTRAINT fk_file_share_event_file FOREIGN KEY(file_id) REFERENCES file_objects(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- V18.4 Media Production Expansion
CREATE TABLE IF NOT EXISTS media_audit_events (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id BIGINT UNSIGNED NOT NULL,
 action VARCHAR(40) NOT NULL,
 resource_type VARCHAR(30) NOT NULL DEFAULT 'media',
 resource_id BIGINT UNSIGNED NULL,
 metadata_json TEXT NULL,
 created_at DATETIME NOT NULL,
 INDEX idx_media_audit_user_time(user_id,created_at),
 INDEX idx_media_audit_resource(resource_type,resource_id),
 CONSTRAINT fk_media_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS media_collections (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 user_id BIGINT UNSIGNED NOT NULL,
 name VARCHAR(180) NOT NULL,
 description VARCHAR(500) NULL,
 created_at DATETIME NOT NULL,
 updated_at DATETIME NOT NULL,
 UNIQUE KEY uq_media_collection_name(user_id,name),
 INDEX idx_media_collections_user(user_id,updated_at),
 CONSTRAINT fk_media_collection_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS media_collection_items (
 collection_id BIGINT UNSIGNED NOT NULL,
 media_id BIGINT UNSIGNED NOT NULL,
 added_at DATETIME NOT NULL,
 PRIMARY KEY(collection_id,media_id),
 INDEX idx_media_collection_item_media(media_id),
 CONSTRAINT fk_media_collection_item_collection FOREIGN KEY(collection_id) REFERENCES media_collections(id) ON DELETE CASCADE,
